async function drawStructure(interactiveCanvas: StructureDisplay, structure: Structure, size: number){
    for (let x = 0; x < size/2;x++){
        for(let y = 0; y < size/2;y++){
            for(let z = 0; z < size/2;z++){
                structure.addBlock([x, y, z], "minecraft:stone")
                //structure.addBlock([x, y, z], ...getRandomBlock())
            }
        }
    }
    interactiveCanvas.setStructure(structure)
}
