let propertyMap:Map<string, {name:string,values:string[]}> = new Map()
Object.entries(BlockProperties).forEach(([blockName,{properties}]) => {
    //if(Object.entries(properties).length>5)console.log(blockName)
    Object.entries(properties).forEach(([propertyName,propertyValues]) => {
        if(propertyMap.has(propertyName))return
        propertyMap.set(propertyName,{name:blockName,values:propertyValues})
    })
})
//console.log(propertyMap)
let block = new BlockHandler("stone")
let blockInfo = new BlockInfo(block)
let searchDialog = new BlockSearchDialog(block)

let twithLogin = new TwitchLogin()
const size = 20;
getResources().then(resources=>{
    const blockRender = new StructureRenderer(
        getGl("block-preview-canvas"),
        new Structure([1, 1, 1]), 
        resources
    )
    let blockDisplay = new BlockDisplay(blockRender, block)
    const structureRenderer = new StructureRenderer(
        getGl("render-canvas"),
        new Structure([size, size, size]), 
        resources
    )
    let structureDisplay = new StructureDisplay(structureRenderer, block, blockDisplay)
})