import type { BlockHandler } from "../utility/blockHandler";
import { getElement } from "../utility/getElement";
import { idToName } from "../utility/idToName";
import BlockProperties from "../resources/blockProperties.json";

export class BlockInfo{
    private itemNameSpan = getElement<HTMLSpanElement>("item-name");
    private propertiesList = getElement<HTMLUListElement>("item-properties");
    constructor(private block:BlockHandler){
        this.itemNameSpan.innerText = this.block.toName()
        this.block.onBlockChanged(this.update.bind(this))
    }
    update(name:string,properties?: {[key: string]: string; }) {
        this.itemNameSpan.innerText = idToName(name)
        this.propertiesList.innerHTML = "";
        if(properties===undefined)return
        Object.entries(properties).forEach(([propertyName,propertyValue])=>
            this.addProperty(propertyName,propertyValue)
        )
    }
    private createToggleProperty(name:string,value:string){
        const propValue = document.createElement("input")
        propValue.type = "checkbox";
        propValue.classList.add("property-toggle");
        propValue.checked = value==="true"?true:false;
        propValue.addEventListener("change", () => {
            this.block.setProperty(name,propValue.checked?"true":"false")
        })
        return propValue
    }
    private createSliderProperty(name:string,value:string){
        const scale = this.block.getPropertyOptions(name)
        const propValue = document.createElement("input");
        propValue.classList.add("property-slider");
        propValue.type = "range";
        propValue.min = scale[0]!;
        propValue.max = scale[scale.length-1]!;
        propValue.value = value;
        propValue.addEventListener("change", () => {
            this.block.setProperty(name,propValue.value)
        })
        return propValue
    }
    private createStringProperty(name:string,value:string){
        const propValue = document.createElement("span");
        propValue.classList.add("property-string");
        propValue.textContent = idToName(value);
        propValue.addEventListener("click", () => {
            const rect = propValue.getBoundingClientRect();
            const optionsList = this.createPropertyOptions(name)
            optionsList.style.position = "absolute";
            optionsList.style.zIndex = "1000";
            if(document.body.clientWidth<=768){
                optionsList.style.left=(rect.left+rect.width/2-optionsList.clientWidth/2)+"px"
                optionsList.style.top = rect.bottom + "px";
            }else{
                optionsList.style.top = (rect.top+rect.height/2-optionsList.clientHeight/2)+"px"
                optionsList.style.left=rect.right+"px"
            }
        })
        return propValue
    }
    private createPropertyValue(name:string,value:string){
        if(!isNaN(Number(value))) return this.createSliderProperty(name,value)
        if(value==="true" || value==="false") return this.createToggleProperty(name,value)
        return this.createStringProperty(name,value)
    }
    addProperty(name: string, value: string) {
        const li = document.createElement("li");
        const propName = document.createElement("span");
        propName.className = "property-name";
        propName.textContent = idToName(name);
        li.appendChild(propName);
        const propValue = this.createPropertyValue(name,value);
        propValue.classList.add("property-value");
        li.appendChild(propValue);
        this.propertiesList.appendChild(li);
    }
    createPropertyOptions(name:string){
        document.querySelectorAll(".value-options").forEach(el => el.remove());
        let optionsList = document.createElement("ul");
        optionsList.className = "value-options";
        this.block.getPropertyOptions(name).forEach(option=>{
            const optionItem = document.createElement("li");
            optionItem.textContent = idToName(option);
            optionItem.addEventListener("click", () => {
                this.block.setProperty(name,option)
                optionsList.remove();
            });
            getElement<HTMLButtonElement>("dialog-open-button").addEventListener("click", () => {
                optionsList.remove();
            })
            optionsList.appendChild(optionItem);
        })
        document.body.appendChild(optionsList);
        return optionsList
    }
}