import { BlockDefinition, BlockModel, Identifier,type Resources, TextureAtlas, upperPowerOfTwo } from "deepslate"
import blockDefinitionJson from "../resources/blockDefinitions.json"
import blockModelJson from "../resources/blockModels.json"
import blockPropertiesJson from "../resources/blockProperties.json"
import blockUvJson from "../resources/blockUvs.json"
function getBlockDefinitions(){
	const blockDefinitions: Record<string, BlockDefinition> = {}
	for (const [id, value] of Object.entries(blockDefinitionJson)) {
		blockDefinitions['minecraft:' + id] = BlockDefinition.fromJson(value)
	}
	return blockDefinitions as Record<`minecraft:${keyof typeof blockDefinitionJson}`, BlockDefinition>
}
function getBlockModels(){
	const blockModels: Record<string, BlockModel> = {}
	for (const [id, value] of Object.entries(blockModelJson)) {
		let blockModel = BlockModel.fromJson(value);
		blockModels['minecraft:' + id] = blockModel;
	}
	Object.values(blockModels).forEach((blockModel) =>
		blockModel.flatten({ getBlockModel: (id: Identifier) => 
			blockModels[id.toString()]??null 
		})
	)
	return blockModels as Record<`minecraft:${keyof typeof blockModelJson}`, BlockModel>
}
function getIdMap(atlasSize:number){
	const uvMap = blockUvJson
	const idMap:Record<string, [number, number, number, number]> = {}
	Object.keys(uvMap).forEach(id => {
		const [u, v, du, dv] = uvMap[id as keyof typeof uvMap] as [number, number, number, number]
		const dv2 = (du !== dv && id.startsWith('block/')) ? du : dv
        const index = Identifier.create(id).toString();
		idMap[index] = [u / atlasSize, v / atlasSize, (u + du) / atlasSize, (v + dv2) / atlasSize]
	})
	return idMap;
}
async function getTextureAtlas(){
	const atlas = new Image()
	atlas.crossOrigin = 'Anonymous'
	atlas.src = './resources/atlas.png'//'/public/resources/atlas.png'
	await atlas.decode()
	const atlasCanvas = document.createElement('canvas')
	const atlasSize = upperPowerOfTwo(Math.max(atlas.width, atlas.height))
	atlasCanvas.width = atlasSize
	atlasCanvas.height = atlasSize
	const atlasCtx = atlasCanvas.getContext('2d')!
	atlasCtx.drawImage(atlas, 0, 0)
	const atlasData = atlasCtx.getImageData(0, 0, atlasSize, atlasSize)
	const idMap = getIdMap(atlasSize)
	return new TextureAtlas(atlasData, idMap)
}
export default async function getResources(){
	const blockDefinitions = getBlockDefinitions();
	const blockModels = getBlockModels();
    const textureAtlas = await getTextureAtlas()
    const resources: Resources = {
		getBlockDefinition(id) { return blockDefinitions[id.toString() as keyof typeof blockDefinitions]??null },
		getBlockModel(id) { return blockModels[id.toString() as keyof typeof blockModels]??null },
		getTextureUV(id) { return textureAtlas.getTextureUV(id) },
		getTextureAtlas() { return textureAtlas.getTextureAtlas() },
		getBlockFlags(id) { return { opaque: false } },
		getBlockProperties(id) { return null },
		getDefaultBlockProperties(id) { return null }
	}
    return resources
}