export function getGl(canvasId:string):WebGLRenderingContext{
    const canvas = document.getElementById(canvasId) as HTMLCanvasElement|null;
    if(canvas===null)throw Error(`No canvas named ${canvasId} found`);
    const gl = canvas.getContext("webgl");
    if(gl===null)throw Error(`Canvas named ${canvasId} has no webgl context`);
    return gl
}