import { getElement } from "./utility/getElement";

const clientId = "murohlwac0uqcy6s1ej8swyofh0684";
const redirectUri = "http://localhost:5500/public/auth.html";
const scope = [
  'user:read:email',
  'user:read:subscriptions'
].join(' ');
const authUrl = `https://id.twitch.tv/oauth2/authorize?client_id=${clientId}&redirect_uri=${encodeURIComponent(
  redirectUri
)}&response_type=token&scope=${encodeURIComponent(scope)}`;
export class TwitchLogin {
    constructor() {
        const loginBtn = getElement<HTMLButtonElement>("twitch-login")
        loginBtn.addEventListener("click", () => {
            const width = 500;
            const height = 600;
            const left = window.screenX + (window.outerWidth - width) / 2;
            const top = window.screenY + (window.outerHeight - height) / 2;
    
            const popup = window.open(
                authUrl,
                "Twitch Login",
                `width=${width},height=${height},left=${left},top=${top}`
            );
            window.addEventListener("message", (event) => {
                if (event.origin !== window.location.origin) return;
    
                const token = event.data.access_token;
                if (token) {
                    console.log("Twitch Access Token:", token);
                    popup?.close();
                    alert("Logged in with Twitch!");
                    this.isUserSubscribed(token, "CastCrafter").then(console.log);
                }
            });
        })
    }
    async getUserInfo(accessToken: string){
        const res = await fetch('https://api.twitch.tv/helix/users', {
            headers: {
            'Authorization': `Bearer ${accessToken}`,
            'Client-Id': clientId,
            },
        });

        const data = await res.json();
        return data.data[0]; // contains id, login, email, etc.
    };
    async checkSubscription(accessToken: string, broadcasterId: string, userId: string){
        const res = await fetch(`https://api.twitch.tv/helix/subscriptions/user?broadcaster_id=${broadcasterId}&user_id=${userId}`, {
            headers: {
            'Authorization': `Bearer ${accessToken}`,
            'Client-Id': clientId,
            },
        });

        if (!res.ok) {
            const err = await res.json();
            console.error('Error checking subscription:', err);
            throw new Error(err.message);
        }

        const data = await res.json();

        // If `data.data` is empty, the user is not subscribed
        return data.data.length > 0;
    };
    async getBroadcasterId(
        accessToken: string,
        channelLogin: string
        ): Promise<string | null> {
        const res = await fetch(`https://api.twitch.tv/helix/users?login=${channelLogin}`, {
            headers: {
            'Authorization': `Bearer ${accessToken}`,
            'Client-Id': clientId,
            },
        });

        if (!res.ok) {
            const err = await res.json();
            console.error('Error fetching broadcaster:', err);
            throw new Error(err.message);
        }

        const data = await res.json();

        if (data.data.length === 0) {
            console.warn('Channel not found');
            return null;
        }

        return data.data[0].id; // ← This is the broadcaster_id
    }
    async isUserSubscribed(accessToken: string, broadcasterName: string) {
        const user = await this.getUserInfo(accessToken);
        console.log(user);
        const broadcaster = await this.getBroadcasterId(accessToken, broadcasterName)??"";
        console.log(broadcaster);
        const subscribed = await this.checkSubscription(accessToken, broadcaster, user.id);
        return subscribed;
    }
}