import { Structure, StructureRenderer, type Resources } from "deepslate";
import { mat4, vec3 } from 'gl-matrix';
import type { BlockHandler } from "../utility/blockHandler";

export class BlockDisplay{
    private center:[number, number, number] = [0.5, 0.5, 0.5];
    private cameraUp = vec3.fromValues(0, 1, 0);
    private newViewMatrix = mat4.create();
    private lastTime = 0
    private rotation = 0
    constructor(private renderer: StructureRenderer,private block: BlockHandler){
        this.setBlock(...this.block.getBlock)
        this.block.onBlockChanged(this.setBlock.bind(this))
    }
    setBlock(name: string, properties?: {
        [key: string]: string;
    }){
        this.renderer.setStructure(
            new Structure([1, 1, 1])
                .addBlock([0, 0, 0], name, properties)
        )
        this.redraw()
    }
    updateAngles(pitch:number,yaw:number){
        const distance = 1.5;
        const x = distance * Math.cos(pitch) * Math.sin(yaw);
        const y = distance * Math.sin(pitch);
        const z = distance * Math.cos(pitch) * Math.cos(yaw);
        const newCameraPos = vec3.fromValues(
            this.center[0] + x,
            this.center[1] + y,
            this.center[2] + z
        );
        mat4.lookAt(this.newViewMatrix, newCameraPos, this.center, this.cameraUp);
        this.redraw()
    }
    private redraw(){
        requestAnimationFrame((t) => this.renderer.drawStructure(this.newViewMatrix));
    }
}