import { idToName } from "./idToName";
import BlockProperties from '../resources/blockProperties.json';

export class BlockHandler{
    private blockChangedCallbacks: ((name: string, properties?: {
        
    })=>void)[] = []
    constructor(private name: string,private properties?: {
        [key: string]: string;
    }){

    }
    setBlock(name: string, properties?: {
        [key: string]: string;
    }){
        let sameProperties = true;
        Object.keys(this.properties||{}).forEach(key => {
            if(this.properties?.[key] !== properties?.[key]){
                sameProperties = false;
            }
        })
        if(this.name === name&&sameProperties) return
        this.name = name
        this.properties = properties
        this.blockChangedCallbacks.forEach(callback => callback(this.name, this.properties))
    }
    setDefault(name:string){
        this.setBlock(name,BlockProperties[name as keyof typeof BlockProperties].defaultValues)
    }
    get getBlock(): [string, { [key: string]: string; }|undefined] {
        return [this.name,this.properties]
    }
    getPropertyOptions(propertyName:string){
        const properties = BlockProperties[this.name as keyof typeof BlockProperties].properties as Record<string, string[]>
        return properties[propertyName] as string[]
    }
    setProperty(propertyName:string,value:string){
        if(!(propertyName in (this.properties||{}))) return
        if(this.properties?.[propertyName] === value) return
        const newProperties = {...this.properties,[propertyName]:value}
        this.setBlock(this.name,newProperties)
    }
    onBlockChanged(callback: (name: string, properties?: {
        [key: string]: string;
    }) => void) {
        this.blockChangedCallbacks.push(callback)
    }
    toName(){
        return idToName(this.name)
    }
    get getName(){
        return this.name
    }
    get getProperties(){
        return this.properties
    }
}