import FuzzySearch from 'fuzzy-search';
import BlockNames from '../resources/blockNames.json';
import BlockProperties from '../resources/blockProperties.json';
import { getElement } from '../utility/getElement';
import type { BlockHandler } from '../utility/blockHandler';
import { idToName } from '../utility/idToName';
export class BlockSearchDialog {
    private fuzzySearch:FuzzySearch<string> = new FuzzySearch(BlockNames,[], {caseSensitive: false, sort: true});
    private dialog:HTMLDivElement = getElement<HTMLDivElement>("dialog")
    private openButton:HTMLButtonElement = getElement<HTMLButtonElement>("dialog-open-button")
    private closeButton:HTMLButtonElement = getElement<HTMLButtonElement>("dialog-close-button")
    private input:HTMLInputElement = getElement<HTMLInputElement>("block-search-input")
    private results:HTMLUListElement = getElement<HTMLUListElement>("block-search-results")
    constructor(private blockHandler:BlockHandler) {
        this.openButton.addEventListener('click', (e)=>{
            this.dialog.classList.add("show");
        })
        this.closeButton.addEventListener('click', (e)=>{
            this.dialog.classList.remove("show");
        })
        this.input.addEventListener('input', (e)=>{
            this.results.innerHTML = "";
            if(this.input.value==="")return
            const query = this.input.value.replace(/ /g, '');
            this.fuzzySearch.search(query).forEach(this.addResult.bind(this))
        })
    }
    addResult(searchResult:string){
        let li = document.createElement("li");
        li.classList.add("block-search-result");
        li.innerText = idToName(searchResult);
        li.addEventListener('click', (e)=>{
            this.input.value = "";
            this.results.innerHTML = "";
            this.blockHandler.setDefault(searchResult)
            this.dialog.classList.remove("show");
        })
        this.results.appendChild(li);
    }
}